let mut steps = 0_u32;
while runtime.is_replaying() {
    if steps >= MAX_STEP_TICKS {
        return Err(RuntimeDebugError::BudgetExceeded(format!(
            "replay exceeded the {MAX_STEP_TICKS}-tick host budget"
        )));
    }
    runtime.tick_fixed_debug_step().map_err(tick_error)?;
